train, test = y[:-12], y[-12:]
def mase(actual, pred, history, m=12):
    scale = np.mean(np.abs(history.values[m:] - history.values[:-m]))
    return np.mean(np.abs(actual.values - pred)) / scale
def report(name, pred, actual=test, hist=train):
    pred = np.asarray(pred)
    return {"model": name, "MAE": np.mean(np.abs(actual.values - pred)),
            "MAPE_%": 100 * np.mean(np.abs(actual.values - pred) / actual.values), "MASE": mase(actual, pred, hist)}
rows = [report("naive", np.repeat(train.iloc[-1], 12)), report("seasonal naive", train.iloc[-12:].values)]
print(pd.DataFrame(rows).round(3))
